def compute(vars):
    values = {
        "2019": vars["v1"],
        "2018": vars["v2"],
        "2017": vars["v3"],
    }
    highest = max(values.values())
    years = [year for year, value in values.items() if value == highest]
    result = " and ".join(years)

    return {
        "value": result,
        "trace": {
            "values_by_year": values,
            "highest_value": highest,
            "matching_years": years,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year",
            },
        },
    }
